const norm = s => String(s || "").normalize("NFD").replace(/\p{Diacritic}/gu, "").toLowerCase().replace(/[^a-z0-9]+/g, " ").trim();
let index;
// "SC", "São José" → "Florianópolis"  (null se não achar)
export function regionOf(uf, city) {
  if (!index) {
    index = new Map();
    for (const [st, text] of Object.entries(DATA))
      for (const part of text.split(";")) {
        const [region, cities] = part.split(":");
        for (const c of cities.split(",")) index.set(st + "|" + c, region);
      }
  }
  return index.get(uf + "|" + norm(city)) || null;
}
